	maxk.ndarray( x.length, 3, x, 1, 0, out, 1, true ); // $ExpectError
	maxk.ndarray( x.length, 3, x, 1, 0, out, 1, false ); // $ExpectError
	maxk.ndarray( x.length, 3, x, 1, 0, out, 1, null ); // $ExpectError
	maxk.ndarray( x.length, 3, x, 1, 0, out, 1, undefined ); // $ExpectError
	maxk.ndarray( x.length, 3, x, 1, 0, out, 1, [] ); // $ExpectError
	maxk.ndarray( x.length, 3, x, 1, 0, out, 1, {} ); // $ExpectError
	maxk.ndarray( x.length, 3, x, 1, 0, out, 1, ( x: number ): number => x ); // $ExpectError
